package com.example.starter.batch.dto;

import com.example.starter.batch.ApprovalRole;
import com.example.starter.batch.BatchStatus;

import java.time.Instant;

/**
 * 批准响应，携带批准序号与批准后的批次状态。
 */
public record ApprovalResponse(
        String batchKey,
        String actorId,
        ApprovalRole role,
        int sequence,
        BatchStatus batchStatus,
        Instant createdAt
) {
}

package com.example.starter.batch.dto;

import com.example.starter.batch.BatchStatus;

import java.time.Instant;
import java.util.List;

/**
 * 拆分响应。父批状态落定 SPLIT；子批初始 QUARANTINED，继承父批产品编码、
 * 生产 UTC 时间与必做检验项，不继承检验或批准记录。splitAt 为 UTC instant。
 */
public record SplitResponse(
        String parentBatchKey,
        BatchStatus parentStatus,
        List<SplitChild> children,
        Instant splitAt
) {

    /**
     * 拆分产生的子批概要。
     */
    public record SplitChild(
            String batchKey,
            String batchNo,
            String productCode,
            Instant producedAt,
            BatchStatus status,
            List<String> requiredTests,
            Instant createdAt
    ) {
    }
}

