102	        MvcResult parentHistory = mockMvc.perform(get("/api/batches/" + parent + "/history"))
103	                .andExpect(status().isOk()).andReturn();
104	        JsonNode parentNode = objectMapper.readTree(parentHistory.getResponse().getContentAsString());
105	        assertEquals(2, parentNode.path("tests").size());
106	        assertEquals(2, parentNode.path("approvals").size());
107	
108	        // 血缘关系落库
109	        assertEquals(3, jdbc.queryForObject(
110	                "SELECT COUNT(*) FROM batch_lineage WHERE parent_key = ?", Integer.class, parent));
111	    }
112	
113	    @Test
114	    void childBatch_canBeReleasedAndSplitAgain() throws Exception {
115	        String parent = "BK-ML-P-" + unique();
116	        createBatch(parent, List.of("t1"), 201);
117	        releaseBatch(parent, "insp-1");
118	        String child = "BK-ML-C-" + unique();
