596	                        .header("X-Actor-Id", actor).header("X-Approval-Role", role)
597	                        .contentType(MediaType.APPLICATION_JSON)
598	                        .content("{\"commandKey\":\"" + commandKey + "\"}"))
599	                .andExpect(status().is(expected));
600	    }
601	
602	    private void recall(String batchKey, String actor, String reason, String commandKey, int expected)
603	            throws Exception {
604	        mockMvc.perform(post("/api/batches/" + batchKey + "/recall")
605	                        .header("X-Actor-Id", actor)
606	                        .contentType(MediaType.APPLICATION_JSON)
607	                        .content("{\"commandKey\":\"" + commandKey + "\",\"reason\":\"" + reason
608	                                + "\"}"))
609	                .andExpect(status().is(expected));
610	    }
611	
612	    private List<String[]> twoChildren() {
